import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] A = new int[n];

        for (int i = 0; i < n; i++) {
            A[i] = sc.nextInt();
        }

        sc.close();
        final int mod = 998244353;
        long[] dp = new long[n + 1];
        dp[0] = 1;

        for (int i = 0; i < n; i++) {
            for (int x = 0; i + A[i] * x <= n; x++) {
                dp[i + A[i] * x] = (dp[i + A[i] * x] + dp[i]) % mod;
            }
        }

        long ans = 0;
        for (int i = 0; i <= n; i++) {
            ans = (ans + dp[i]) % mod;
        }

        System.out.println(ans);
    }
}
